import React from "react";

export function RiskGauge({ score = 0, size = 96, strokeWidth = 8, showLabel = true }) {
  const clamped = Math.min(Math.max(Number(score) || 0, 0), 100);
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (clamped / 100) * circumference;

  let colorClass = "text-emerald-500";
  let bgGlow = "shadow-emerald-500/10";
  let labelText = "Low Risk";

  if (clamped >= 75) {
    colorClass = "text-rose-500";
    bgGlow = "shadow-rose-500/20";
    labelText = "Critical Flag";
  } else if (clamped >= 50) {
    colorClass = "text-orange-500";
    bgGlow = "shadow-orange-500/20";
    labelText = "High Risk";
  } else if (clamped >= 25) {
    colorClass = "text-amber-500";
    bgGlow = "shadow-amber-500/10";
    labelText = "Medium Risk";
  }

  return (
    <div className="flex flex-col items-center justify-center">
      <div className={`relative flex items-center justify-center ${bgGlow}`} style={{ width: size, height: size }}>
        <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${size} ${size}`}>
          {/* Track */}
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={strokeWidth}
            className="text-audit-800 fill-none"
            stroke="currentColor"
          />
          {/* Progress */}
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={strokeWidth}
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            className={`${colorClass} fill-none transition-all duration-700 ease-out`}
            stroke="currentColor"
          />
        </svg>

        <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
          <span className="text-xl sm:text-2xl font-extrabold font-mono text-white leading-none">
            {clamped}
          </span>
          <span className="text-[9px] uppercase font-mono text-slate-400 mt-0.5">/100</span>
        </div>
      </div>

      {showLabel && (
        <span className="mt-1.5 text-[11px] font-mono font-semibold uppercase tracking-wider text-slate-300">
          {labelText}
        </span>
      )}
    </div>
  );
}

export default RiskGauge;

