import React, { useEffect, useState } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import {
  ShieldAlert,
  Search,
  Filter,
  RotateCcw,
  AlertTriangle,
  ArrowRight,
  ChevronDown
} from "lucide-react";
import { api } from "../api/client.js";
import { formatINR, formatNumber } from "../utils/formatters.js";
import { RiskBadge } from "../components/common/RiskBadge.jsx";
import { AnomalyTag } from "../components/common/AnomalyTag.jsx";

export function AnomaliesTriagePage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();

  // Filters from query string
  const typeFilter = searchParams.get("type") || "all";
  const severityFilter = searchParams.get("severity") || "all";
  const stateFilter = searchParams.get("state") || "all";
  const categoryFilter = searchParams.get("category") || "all";
  const search = searchParams.get("search") || "";

  const [searchInput, setSearchInput] = useState(search);
  const [showMoreFilters, setShowMoreFilters] = useState(false);
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const anomalyTypes = [
    { id: "all", label: "All Anomalies" },
    { id: "Cost Overrun", label: "Cost Overrun" },
    { id: "Duplicate Work", label: "Duplicate Work" },
    { id: "Delayed Project", label: "Stalled / Delay" },
    { id: "Unusual Spending", label: "March Rush" },
    { id: "Compliance Violation", label: "Prohibited Work" }
  ];

  const severityOptions = ["all", "CRITICAL", "HIGH", "MEDIUM", "LOW"];
  const states = [
    "all",
    "Andhra Pradesh",
    "Uttar Pradesh",
    "Maharashtra",
    "Bihar",
    "Rajasthan",
    "Tamil Nadu",
    "Karnataka",
    "West Bengal",
    "Assam",
    "Odisha",
    "Nagaland"
  ];
  const categories = [
    "all",
    "Roads & Bridges",
    "Drinking Water",
    "Solar & Renewable Energy",
    "Education",
    "Community Infrastructure",
    "Health & Public Welfare",
    "Sanitation & Public Health",
    "Flood Protection & Irrigation"
  ];

  const fetchAnomalies = () => {
    setLoading(true);
    setError(null);
    api
      .getAnomalies({
        type: typeFilter,
        severity: severityFilter,
        state: stateFilter,
        category: categoryFilter,
        search
      })
      .then((res) => {
        setProjects(res.data || []);
      })
      .catch((err) => {
        setError(err.message || "Failed to fetch anomalies.");
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchAnomalies();
  }, [typeFilter, severityFilter, stateFilter, categoryFilter, search]);

  const updateFilter = (key, value) => {
    const params = new URLSearchParams(searchParams);
    if (value && value !== "all") {
      params.set(key, value);
    } else {
      params.delete(key);
    }
    setSearchParams(params);
  };

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    updateFilter("search", searchInput.trim());
  };

  const resetFilters = () => {
    setSearchInput("");
    setSearchParams({});
  };

  const hasExtraFilters = severityFilter !== "all" || stateFilter !== "all" || categoryFilter !== "all";

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
        <div>
          <h1 className="text-lg sm:text-xl font-bold text-white tracking-tight flex items-center gap-2 font-mono">
            <ShieldAlert className="w-5 h-5 text-rose-400" />
            Anomaly Triage Worklist
          </h1>
          <p className="text-xs text-slate-400 mt-0.5 font-mono">
            Review and investigate automated flags across all monitored MPLADS works.
          </p>
        </div>
        <div className="text-xs font-mono text-slate-400 self-start sm:self-auto">
          Showing <strong className="text-white">{projects.length}</strong> flagged cases
        </div>
      </div>

      {/* 5. Triage Filters: Search + Anomaly Tabs + Compact Filter Dropdown */}
      <div className="p-3.5 rounded-xl border border-audit-800 bg-audit-900/90 space-y-3 shadow-sm">
        {/* Search Bar & Anomaly Tabs */}
        <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3">
          {/* Keyword Search */}
          <form onSubmit={handleSearchSubmit} className="relative flex-1 max-w-md">
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="Search by code, title, MP, district..."
              className="w-full pl-8 pr-7 py-1.5 text-xs bg-audit-950 border border-audit-700/80 rounded-lg text-slate-100 placeholder-slate-500 focus:outline-none focus:ring-1 focus:ring-cyan-500 font-mono"
            />
            <Search className="w-3.5 h-3.5 text-slate-500 absolute left-2.5 top-2 pointer-events-none" />
            {searchInput && (
              <button
                type="button"
                onClick={() => {
                  setSearchInput("");
                  updateFilter("search", "");
                }}
                className="absolute right-2 top-1.5 text-slate-400 hover:text-white text-xs"
              >
                ✕
              </button>
            )}
          </form>

          {/* Compact Filter Toggle */}
          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowMoreFilters(!showMoreFilters)}
              className={`px-3 py-1.5 rounded-lg text-xs font-mono font-semibold border transition flex items-center gap-1.5 ${
                hasExtraFilters || showMoreFilters
                  ? "bg-cyan-500/20 text-cyan-300 border-cyan-500/40"
                  : "bg-audit-950 text-slate-400 border-audit-700 hover:text-white"
              }`}
            >
              <Filter className="w-3 h-3" />
              <span>Filters</span>
              {hasExtraFilters && (
                <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 ml-0.5" />
              )}
              <ChevronDown className={`w-3 h-3 transition-transform ${showMoreFilters ? "rotate-180" : ""}`} />
            </button>

            {(typeFilter !== "all" || hasExtraFilters || search) && (
              <button
                onClick={resetFilters}
                className="p-1.5 rounded-lg border border-audit-700 text-slate-400 hover:text-white hover:bg-audit-800 transition"
                title="Reset all filters"
              >
                <RotateCcw className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        </div>

        {/* Anomaly Category Tabs */}
        <div className="flex flex-wrap gap-1.5 pt-1 border-t border-audit-800/60">
          {anomalyTypes.map((tab) => {
            const active = typeFilter === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => updateFilter("type", tab.id)}
                className={`px-2.5 py-1 rounded-md text-xs font-mono font-medium transition ${
                  active
                    ? "bg-cyan-500/20 text-cyan-300 border border-cyan-500/40"
                    : "text-slate-400 hover:text-slate-200 hover:bg-audit-800 border border-transparent"
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* Collapsible Secondary Filters: Severity, State, Category */}
        {showMoreFilters && (
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5 pt-2.5 border-t border-audit-800">
            <div>
              <label className="text-[10px] font-mono text-slate-400 block mb-1">Severity Tier</label>
              <select
                value={severityFilter}
                onChange={(e) => updateFilter("severity", e.target.value)}
                className="w-full py-1 px-2 text-xs bg-audit-950 border border-audit-700 rounded text-slate-200 font-mono"
              >
                <option value="all">All Severities</option>
                {severityOptions.filter(s => s !== 'all').map(s => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-[10px] font-mono text-slate-400 block mb-1">State</label>
              <select
                value={stateFilter}
                onChange={(e) => updateFilter("state", e.target.value)}
                className="w-full py-1 px-2 text-xs bg-audit-950 border border-audit-700 rounded text-slate-200 font-mono"
              >
                <option value="all">All States</option>
                {states.filter(st => st !== 'all').map(st => (
                  <option key={st} value={st}>{st}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-[10px] font-mono text-slate-400 block mb-1">Category</label>
              <select
                value={categoryFilter}
                onChange={(e) => updateFilter("category", e.target.value)}
                className="w-full py-1 px-2 text-xs bg-audit-950 border border-audit-700 rounded text-slate-200 font-mono truncate"
              >
                <option value="all">All Categories</option>
                {categories.filter(c => c !== 'all').map(c => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>
          </div>
        )}
      </div>

      {/* 6. Triage Results (Concise Investigation Rows) */}
      {loading ? (
        <div className="space-y-2.5 animate-pulse">
          {[1, 2, 3, 4, 5].map((i) => (
            <div key={i} className="h-20 bg-audit-900 border border-audit-800 rounded-xl" />
          ))}
        </div>
      ) : error ? (
        <div className="p-6 rounded-xl border border-rose-500/30 bg-rose-950/20 text-rose-300 text-center text-xs">
          {error}
        </div>
      ) : projects.length === 0 ? (
        <div className="p-8 text-center rounded-xl border border-audit-800 bg-audit-900/60 space-y-2">
          <ShieldAlert className="w-6 h-6 text-slate-500 mx-auto" />
          <h3 className="font-bold text-xs text-slate-300">No matching projects found</h3>
          <button
            onClick={resetFilters}
            className="px-2.5 py-1 rounded text-xs font-mono bg-cyan-600 text-white mt-1"
          >
            Reset Filters
          </button>
        </div>
      ) : (
        <div className="space-y-2.5">
          {projects.map((project) => {
            const primaryFlag = project.anomalies[0];
            return (
              <div
                key={project.id}
                onClick={() => navigate(`/projects/${project.id}`)}
                className="p-3.5 rounded-xl border border-audit-800 bg-audit-900/90 hover:bg-audit-850 hover:border-cyan-500/40 cursor-pointer transition flex flex-col md:flex-row md:items-center justify-between gap-3 group"
              >
                {/* Left: Badges, Title, and Primary Evidence Sentence */}
                <div className="space-y-1.5 flex-1 min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <RiskBadge level={project.riskLevel} size="sm" />
                    <AnomalyTag type={project.primaryAnomaly} size="sm" />
                    <span className="font-mono text-xs font-bold text-cyan-400">
                      {project.workCode}
                    </span>
                    <span className="text-[11px] font-mono text-slate-400">
                      {project.district}, {project.state} • MP: {project.mpName}
                    </span>
                  </div>

                  <h3 className="text-xs sm:text-sm font-bold text-white group-hover:text-cyan-300 transition truncate">
                    {project.title}
                  </h3>

                  {/* Primary Evidence Sentence */}
                  {primaryFlag && (
                    <p className="text-xs text-slate-400 flex items-center gap-1.5 line-clamp-1">
                      <span className="text-rose-400 font-semibold flex-shrink-0">Evidence:</span>
                      <span>{primaryFlag.explanation}</span>
                    </p>
                  )}
                </div>

                {/* Right: Sanctioned Value & Action */}
                <div className="flex items-center justify-between md:justify-end gap-4 flex-shrink-0 pt-2 md:pt-0 border-t md:border-t-0 border-audit-800/60">
                  <div className="text-right">
                    <span className="text-[10px] font-mono uppercase text-slate-500 block">Sanctioned</span>
                    <span className="font-mono font-bold text-xs sm:text-sm text-white">
                      {formatINR(project.sanctionedAmount)}
                    </span>
                  </div>

                  <button className="px-3 py-1.5 rounded-lg text-xs font-mono font-bold bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 transition flex items-center gap-1">
                    Inspect Dossier
                    <ArrowRight className="w-3 h-3" />
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default AnomaliesTriagePage;

import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import {
  Scale,
