export function CompliancePage() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    api
      .getCompliance()
      .then((res) => {
        setData(res.data);
      })
      .catch((err) => {
        setError(err.message || "Failed to load statutory compliance data.");
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="space-y-4 py-4 animate-pulse">
        <div className="h-6 w-48 bg-audit-800 rounded" />
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-20 bg-audit-900 border border-audit-800 rounded-xl" />
          ))}
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="p-6 rounded-xl border border-rose-500/30 bg-rose-950/20 text-center">
        <p className="text-xs text-rose-400">{error || "Failed to load compliance data."}</p>
      </div>
    );
  }

  const { mpSummaries, prohibitedWorksCount } = data;
  const compliantCount = mpSummaries.filter((m) => m.complianceStatus === "Compliant").length;
  const nonCompliantCount = mpSummaries.length - compliantCount;

  return (
    <div className="space-y-5">
      {/* Header */}
      <div>
        <h1 className="text-lg sm:text-xl font-bold text-white tracking-tight flex items-center gap-2 font-mono">
          <Scale className="w-5 h-5 text-cyan-400" />
          Statutory Quota Compliance
        </h1>
        <p className="text-xs text-slate-400 mt-0.5 font-mono">
          Monitoring MP-wise compliance with mandatory SC (15%) & ST (7.5%) allocation quotas.
        </p>
      </div>

      {/* Compliance Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5">
        <div className="p-4 rounded-xl border border-audit-800 bg-audit-900/90 space-y-1">
          <span className="text-[10px] font-mono uppercase text-slate-400">Statutory Quota Target</span>
          <div className="text-xl font-bold font-mono text-cyan-400">22.5%</div>
          <p className="text-[11px] text-slate-400">15.0% SC + 7.5% ST</p>
        </div>

        <div className="p-4 rounded-xl border border-amber-500/30 bg-gradient-to-br from-audit-900 to-amber-950/20 space-y-1">
          <span className="text-[10px] font-mono uppercase text-amber-400">Quota Deficit Members</span>
          <div className="text-xl font-bold font-mono text-amber-300">
            {nonCompliantCount} / {mpSummaries.length}
          </div>
          <p className="text-[11px] text-amber-400/80">Below mandatory 22.5% allocation</p>
        </div>

        <div className="p-4 rounded-xl border border-rose-500/30 bg-gradient-to-br from-audit-900 to-rose-950/20 space-y-1">
          <span className="text-[10px] font-mono uppercase text-rose-400">Prohibited Items Flagged</span>
          <div className="text-xl font-bold font-mono text-rose-300">
            {prohibitedWorksCount}
          </div>
          <p className="text-[11px] text-rose-400/80">Violations of Schedule-II (Private/Religious trusts)</p>
        </div>
      </div>

      {/* 10. Simplified MP-by-MP SC/ST Compliance Table */}
      <div className="p-4 rounded-xl border border-audit-800 bg-audit-900/90 space-y-3 shadow-sm">
        <div className="flex items-center justify-between">
          <h2 className="text-xs font-bold text-white uppercase tracking-wider font-mono flex items-center gap-2">
            <Users className="w-3.5 h-3.5 text-cyan-400" />
            MP Quota Allocation Ratios
          </h2>
          <span className="text-[11px] font-mono text-slate-400">
            Target: ≥ 22.5%
          </span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-audit-950 text-slate-400 font-mono border-b border-audit-800 uppercase text-[10px]">
              <tr>
                <th className="py-2.5 px-3">Hon'ble MP</th>
                <th className="py-2.5 px-3">State</th>
                <th className="py-2.5 px-3">Allocation Ratio</th>
                <th className="py-2.5 px-3">Status</th>
                <th className="py-2.5 px-3 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-audit-800">
              {mpSummaries.map((mp, i) => {
                const isCompliant = mp.complianceStatus === "Compliant";
                return (
                  <tr key={i} className="hover:bg-audit-850">
                    <td className="py-2.5 px-3 font-semibold text-white">
                      {mp.mpName}
                    </td>
                    <td className="py-2.5 px-3 text-slate-400 font-mono">
                      {mp.state}
                    </td>
                    <td className="py-2.5 px-3">
                      <div className="space-y-1">
                        <span className={`font-mono text-xs ${isCompliant ? "text-emerald-400" : "text-amber-400 font-bold"}`}>
                          {mp.scStPercent}%
                        </span>
                        <div className="h-1.5 w-24 rounded-full bg-audit-950 overflow-hidden">
                          <div
                            className={`h-full ${isCompliant ? "bg-emerald-500" : "bg-amber-500"}`}
                            style={{ width: `${Math.min((mp.scStPercent / 22.5) * 100, 100)}%` }}
                          />
                        </div>
                      </div>
                    </td>
                    <td className="py-2.5 px-3">
                      <span
                        className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-mono font-bold ${
                          isCompliant
                            ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/30"
                            : "bg-amber-500/10 text-amber-400 border border-amber-500/30"
                        }`}
                      >
                        {isCompliant ? (
                          <>
                            <CheckCircle2 className="w-3 h-3" />
                            Compliant
                          </>
                        ) : (
                          <>
                            <AlertTriangle className="w-3 h-3" />
                            Deficit (-{mp.mandateShortfallPercent}%)
                          </>
                        )}
                      </span>
                    </td>
                    <td className="py-2.5 px-3 text-right">
                      <Link
                        to={`/anomalies?search=${encodeURIComponent(mp.mpName)}`}
                        className="px-2 py-1 rounded text-xs font-mono text-cyan-400 hover:text-cyan-300 transition inline-flex items-center gap-1"
                      >
                        Inspect Works
                        <ArrowRight className="w-3 h-3" />
                      </Link>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default CompliancePage;

import React, { useEffect, useState } from "react";
