import { AnomalyTag } from "../components/common/AnomalyTag.jsx";

export function DashboardPage() {
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    api
      .getDashboardStats()
      .then((res) => {
        setData(res.data);
      })
      .catch((err) => {
        setError(err.message || "Failed to load surveillance metrics.");
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <div className="space-y-6 py-4 animate-pulse">
        <div className="h-6 w-48 bg-audit-800 rounded" />
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-24 bg-audit-900 border border-audit-800 rounded-xl" />
          ))}
        </div>
        <div className="h-64 bg-audit-900 border border-audit-800 rounded-xl" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 rounded-xl border border-rose-500/30 bg-rose-950/20 text-rose-300 text-center space-y-2">
        <AlertOctagon className="w-6 h-6 mx-auto text-rose-400" />
        <h3 className="font-bold text-xs font-mono">Failed to load monitoring metrics</h3>
        <p className="text-xs text-rose-400/80">{error}</p>
      </div>
    );
  }

  const { metrics, anomalyTypeCounts, urgentCasesQueue } = data;

  const anomalyFilters = [
    { type: "Cost Overrun", label: "Cost Overrun", count: anomalyTypeCounts["Cost Overrun"] || 0 },
    { type: "Duplicate Work", label: "Duplicate Work", count: anomalyTypeCounts["Duplicate Work"] || 0 },
    { type: "Delayed Project", label: "Stalled / Delayed", count: anomalyTypeCounts["Delayed Project"] || 0 },
    { type: "Unusual Spending", label: "March Rush", count: anomalyTypeCounts["Unusual Spending"] || 0 },
    { type: "Compliance Violation", label: "Prohibited Work", count: anomalyTypeCounts["Compliance Violation"] || 0 }
  ];

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-lg sm:text-xl font-bold text-white tracking-tight flex items-center gap-2 font-mono">
            <Activity className="w-5 h-5 text-cyan-400" />
            MPLADS Anomaly Monitoring
          </h1>
          <p className="text-xs text-slate-400 mt-0.5 font-mono">
            Automated detection of fund anomalies, duplicate sanctions, and stalled works.
          </p>
        </div>

        <Link
          to="/anomalies"
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold font-mono bg-cyan-600 hover:bg-cyan-500 text-white transition self-start sm:self-auto"
        >
          View All Flagged Cases ({metrics.flaggedCount})
          <ArrowRight className="w-3.5 h-3.5" />
        </Link>
      </div>

      {/* 1. Dashboard Metrics (3 Key Cards) */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <MetricCard
          title="Monitored Projects"
          value={formatNumber(metrics.totalProjects)}
          subtitle={`${metrics.normalCount} within normal parameters`}
          icon={Layers}
          variant="default"
        />
        <MetricCard
          title="Flagged Cases"
          value={formatNumber(metrics.flaggedCount)}
          subtitle={`${metrics.criticalCount} Critical • ${metrics.highRiskCount} High Risk`}
          icon={ShieldAlert}
          variant="critical"
        />
        <MetricCard
          title="Value at Risk"
          value={formatINR(metrics.valueAtRisk)}
          subtitle={`${metrics.valueAtRiskPercentage}% of monitored allocation`}
          icon={IndianRupee}
          variant="critical"
        />
      </div>

      {/* 2. Anomaly Categories (Compact Clickable Filter Row) */}
      <div className="p-3.5 rounded-xl border border-audit-800 bg-audit-900/90 space-y-2">
        <span className="text-[10px] font-mono uppercase text-slate-400 font-semibold block">
          Filter by Anomaly Class
        </span>
        <div className="flex flex-wrap gap-2">
          {anomalyFilters.map((cat) => (
            <button
              key={cat.type}
              onClick={() => navigate(`/anomalies?type=${encodeURIComponent(cat.type)}`)}
              className="flex items-center gap-2 px-3 py-1.5 rounded-lg border border-audit-700 bg-audit-950/80 hover:bg-audit-800 hover:border-cyan-500/40 text-xs text-slate-200 transition font-mono group"
            >
              <span>{cat.label}</span>
              <span className="px-1.5 py-0.2 rounded text-[10px] font-bold bg-audit-800 group-hover:bg-cyan-500/20 group-hover:text-cyan-300 text-slate-400">
                {cat.count}
              </span>
            </button>
          ))}
        </div>
      </div>

      {/* 3. Dashboard Priority Cases (Simplified Row Items) */}
      <div className="rounded-xl border border-audit-800 bg-audit-900/90 p-4 sm:p-5 space-y-3 shadow-sm">
        <div className="flex items-center justify-between border-b border-audit-800/80 pb-3">
          <div>
            <h2 className="text-sm font-bold text-white flex items-center gap-2 font-mono">
              <AlertOctagon className="w-4 h-4 text-rose-400" />
              Priority Cases Requiring Investigation
            </h2>
            <p className="text-xs text-slate-400 mt-0.5">
              High-severity flags requiring administrative review or physical audit.
            </p>
          </div>
          <Link
            to="/anomalies"
            className="text-xs font-mono font-semibold text-cyan-400 hover:text-cyan-300 flex items-center gap-1"
          >
            All Cases →
          </Link>
        </div>

        <div className="space-y-2.5">
          {urgentCasesQueue.map((project) => (
            <div
              key={project.id}
              onClick={() => navigate(`/projects/${project.id}`)}
              className="p-3.5 rounded-xl border border-audit-800 bg-audit-950/60 hover:bg-audit-850 hover:border-cyan-500/40 cursor-pointer transition flex flex-col sm:flex-row sm:items-center justify-between gap-3 group"
            >
              <div className="space-y-1 flex-1 min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <RiskBadge level={project.riskLevel} size="sm" />
                  <AnomalyTag type={project.primaryAnomaly} size="sm" />
                  <span className="font-mono text-xs font-bold text-cyan-400">
                    {project.workCode}
                  </span>
                  <span className="text-[11px] font-mono text-slate-400">
                    {project.district}, {project.state}
                  </span>
                </div>

                <h3 className="text-xs font-bold text-white group-hover:text-cyan-300 transition truncate">
                  {project.title}
                </h3>
              </div>

              {/* Single Financial Figure + Action */}
              <div className="flex items-center justify-between sm:justify-end gap-4 flex-shrink-0 pt-2 sm:pt-0 border-t sm:border-t-0 border-audit-800/60">
                <div className="text-right">
                  <span className="text-[10px] font-mono text-slate-500 block uppercase">Sanctioned</span>
                  <span className="text-xs font-mono font-bold text-slate-200">
                    {formatINR(project.sanctionedAmount)}
                  </span>
                </div>

                <button className="px-2.5 py-1 rounded-lg text-xs font-mono font-bold bg-cyan-500/10 hover:bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 transition">
                  Investigate →
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default DashboardPage;

import React, { useEffect, useState } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import {
  ShieldAlert,
  ArrowLeft,
  AlertOctagon,
  AlertTriangle,
  TrendingUp,
  Copy,
  Calendar,
  IndianRupee,
  CheckCircle2,
  UserCheck,
  Send,
  ChevronDown,
  ChevronUp
} from "lucide-react";
import { api } from "../api/client.js";
import { formatINR, formatDate } from "../utils/formatters.js";
import { RiskBadge } from "../components/common/RiskBadge.jsx";
import { AnomalyTag } from "../components/common/AnomalyTag.jsx";

export function ProjectDossierPage() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [dossier, setDossier] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Collapsible supporting sections
  const [showBenchmark, setShowBenchmark] = useState(false);
  const [showDisbursements, setShowDisbursements] = useState(false);
  const [showChecklist, setShowChecklist] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  // Decision Console form state
  const [selectedAction, setSelectedAction] = useState("");
  const [auditorNotes, setAuditorNotes] = useState("");
  const [submittingAction, setSubmittingAction] = useState(false);
  const [actionSuccessMessage, setActionSuccessMessage] = useState(null);

  const fetchDossier = () => {
    setLoading(true);
    setError(null);
    api
      .getProjectById(id)
      .then((res) => {
        setDossier(res.data);
        if (res.data?.project?.decisionSupport?.recommendedAction) {
          setSelectedAction(res.data.project.decisionSupport.recommendedAction);
        }
      })
      .catch((err) => {
        setError(err.message || "Failed to load project forensic dossier.");
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchDossier();
  }, [id]);

  const handleActionSubmit = async (e) => {
    e.preventDefault();
    if (!selectedAction) return;

    setSubmittingAction(true);
    setActionSuccessMessage(null);
    try {
      await api.recordDecision(id, {
        action: selectedAction,
        notes: auditorNotes,
        auditorName: "Senior Audit Officer (MoSPI Central Surveillance)",
        statusOverride: selectedAction.includes("Freeze") ? "Sanction Frozen" : null
      });

      setActionSuccessMessage("Administrative action logged successfully.");
      setAuditorNotes("");
      fetchDossier();
    } catch (err) {
      alert("Failed to submit decision: " + err.message);
    } finally {
      setSubmittingAction(false);
    }
  };

  if (loading) {
    return (
      <div className="space-y-4 py-4 animate-pulse">
        <div className="h-5 w-28 bg-audit-800 rounded" />
        <div className="h-28 bg-audit-900 border border-audit-800 rounded-xl" />
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          <div className="lg:col-span-2 h-72 bg-audit-900 border border-audit-800 rounded-xl" />
          <div className="h-72 bg-audit-900 border border-audit-800 rounded-xl" />
        </div>
      </div>
    );
  }

  if (error || !dossier) {
    return (
      <div className="p-6 rounded-xl border border-rose-500/30 bg-rose-950/20 text-center space-y-3">
        <AlertOctagon className="w-6 h-6 mx-auto text-rose-400" />
        <h3 className="text-xs font-bold font-mono text-rose-300">Dossier Unavailable</h3>
        <p className="text-xs text-rose-400">{error || "Project could not be found."}</p>
        <Link
          to="/anomalies"
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-mono bg-audit-800 text-white"
        >
          <ArrowLeft className="w-3 h-3" />
          Return to Triage
        </Link>
      </div>
    );
  }

  const { project, categoryBenchmark } = dossier;
  const decisionSupport = project.decisionSupport || {};
  const duplicateAnomaly = project.anomalies.find((a) => a.type === "Duplicate Work");

  return (
    <div className="space-y-5">
      {/* Back Navigation */}
      <div>
        <Link
          to="/anomalies"
          className="inline-flex items-center gap-1 text-xs font-mono text-slate-400 hover:text-cyan-400 transition"
        >
          <ArrowLeft className="w-3.5 h-3.5" />
          Back to Anomaly Worklist
        </Link>
      </div>

      {/* 7. Simplified Project Dossier Header Banner */}
      <div className="p-4 sm:p-5 rounded-xl border border-audit-800 bg-audit-900/90 shadow-sm space-y-3">
        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3">
          <div className="space-y-1.5 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <RiskBadge level={project.riskLevel} size="sm" />
              <AnomalyTag type={project.primaryAnomaly} size="sm" />
              <span className="font-mono text-xs font-bold text-cyan-400">
                {project.workCode}
              </span>
              <span className="text-xs font-semibold px-2 py-0.2 rounded bg-audit-800 text-slate-300">
                {project.category}
              </span>
            </div>

            <h1 className="text-base sm:text-lg font-bold text-white leading-snug">
              {project.title}
            </h1>

            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-slate-400 font-mono pt-0.5">
              <span>MP: <strong className="text-slate-200">{project.mpName}</strong></span>
              <span>•</span>
              <span>Location: <strong className="text-slate-200">{project.district}, {project.state}</strong></span>
              <span>•</span>
              <span>Agency: <strong className="text-slate-300">{project.ida}</strong></span>
            </div>
          </div>

          {/* Clean Single Risk Score & Sanctioned Amount Box */}
          <div className="p-3 rounded-lg bg-audit-950 border border-audit-800 text-right flex-shrink-0 self-start sm:self-auto space-y-0.5">
            <div className="text-[10px] font-mono uppercase text-slate-400">Sanctioned Amount</div>
            <div className="text-sm font-bold font-mono text-white">{formatINR(project.sanctionedAmount)}</div>
            <div className="text-[11px] font-mono text-rose-400 font-semibold">
              Risk Score: {project.riskScore}/100
            </div>
          </div>
        </div>
      </div>

      {/* 8 & 9. Main Investigation Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
        {/* LEFT 2 COLS: EVIDENCE & DETAILED ANOMALIES */}
        <div className="lg:col-span-2 space-y-4">
          {/* Section 1: Detected Red Flags (Smoking Gun) */}
          <div className="p-4 sm:p-5 rounded-xl border border-audit-800 bg-audit-900/90 space-y-3">
            <h2 className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-2 font-mono">
              <ShieldAlert className="w-4 h-4 text-rose-400" />
              Automated Forensic Red Flags ({project.anomalies.length})
            </h2>

            <div className="space-y-2.5">
              {project.anomalies.map((flag, idx) => (
                <div
                  key={idx}
                  className={`p-3.5 rounded-xl border space-y-1.5 ${
                    flag.severity === "CRITICAL"
                      ? "bg-rose-950/20 border-rose-500/40 text-rose-200"
                      : "bg-amber-950/20 border-amber-500/40 text-amber-200"
                  }`}
                >
                  <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1">
                    <div className="flex items-center gap-2 font-bold text-xs">
                      <AlertTriangle
                        className={`w-3.5 h-3.5 flex-shrink-0 ${
                          flag.severity === "CRITICAL" ? "text-rose-400" : "text-amber-400"
                        }`}
                      />
                      <span>{flag.title}</span>
                    </div>

                    <span className="font-mono text-xs font-bold px-2 py-0.5 rounded bg-audit-950 border border-audit-800 self-start sm:self-auto">
                      {flag.metric}
                    </span>
                  </div>

                  <p className="text-xs text-slate-300 leading-relaxed">
                    {flag.explanation}
                  </p>

                  <div className="text-[10px] font-mono text-slate-400 pt-1 border-t border-audit-800/60 flex justify-between">
                    <span>Baseline: <strong>{flag.baseline}</strong></span>
                    <span>Impact Weight: +{flag.impactScore} pts</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Section 2: Duplicate Work Side-by-Side Diff (if duplicate exists) */}
          {duplicateAnomaly && duplicateAnomaly.duplicateOf && (
            <div className="p-4 sm:p-5 rounded-xl border border-purple-500/40 bg-purple-950/15 space-y-3">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-bold text-purple-300 flex items-center gap-2 font-mono">
                  <Copy className="w-4 h-4 text-purple-400" />
                  Twin Duplicate Match Analysis
                </h3>
                <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-purple-900/60 text-purple-200 border border-purple-400/40">
                  Suspicious Duplicate
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs">
                {/* Current Project */}
                <div className="p-3 rounded-lg border border-audit-700 bg-audit-950 space-y-1">
                  <span className="text-[10px] font-mono uppercase text-cyan-400 font-bold block">
                    Current Under Audit (Target)
                  </span>
                  <div className="font-mono text-xs font-bold text-white">{project.workCode}</div>
                  <div className="font-semibold text-slate-200">{project.title}</div>
                  <div className="text-slate-400 text-[11px]">MP: {project.mpName}</div>
                  <div className="font-mono font-bold text-white pt-1">
                    Cost: {formatINR(project.sanctionedAmount)}
                  </div>
                </div>

                {/* Matched Twin Project (Clickable Link to Twin Dossier) */}
                <Link
                  to={`/projects/${duplicateAnomaly.duplicateOf.id || duplicateAnomaly.duplicateOf.workCode}`}
                  className="p-3 rounded-lg border border-purple-500/50 bg-audit-950 hover:bg-purple-950/30 hover:border-purple-400 transition space-y-1 block group"
                  title="Click to inspect the twin project dossier"
                >
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-mono uppercase text-purple-400 font-bold block">
                      Existing Matched Work in District
                    </span>
                    <span className="text-[10px] font-mono font-bold text-purple-300 group-hover:underline flex items-center gap-1">
                      Inspect Twin Dossier →
                    </span>
                  </div>
                  <div className="font-mono text-xs font-bold text-purple-300">
                    {duplicateAnomaly.duplicateOf.workCode || duplicateAnomaly.duplicateOf.id}
                  </div>
                  <div className="font-semibold text-slate-200 group-hover:text-white transition">
                    {duplicateAnomaly.duplicateOf.title}
                  </div>
                  <div className="text-slate-400 text-[11px]">
                    MP: {duplicateAnomaly.duplicateOf.mpName}
                  </div>
                  <div className="font-mono font-bold text-white pt-1">
                    Cost: {formatINR(duplicateAnomaly.duplicateOf.sanctionedAmount)} ({duplicateAnomaly.duplicateOf.status})
                  </div>
                </Link>
              </div>
            </div>
          )}

          {/* Section 3: Collapsible Cost Benchmark Analysis */}
          {categoryBenchmark && (
            <div className="p-4 rounded-xl border border-audit-800 bg-audit-900/80 space-y-3">
