                <div className="flex items-center gap-2">
                  <TrendingUp className="w-3.5 h-3.5 text-cyan-400" />
                  <span>Category Cost Benchmark Breakdown</span>
                </div>
                {showBenchmark ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
              </button>

              {showBenchmark && (
                <div className="space-y-3 pt-2 border-t border-audit-800">
                  <div className="grid grid-cols-3 gap-2 text-center text-xs">
                    <div className="p-2.5 rounded bg-audit-950 border border-audit-800">
                      <span className="text-[10px] font-mono uppercase text-slate-500 block">Sanctioned</span>
                      <span className="font-bold font-mono text-rose-400">{formatINR(project.sanctionedAmount)}</span>
                    </div>
                    <div className="p-2.5 rounded bg-audit-950 border border-audit-800">
                      <span className="text-[10px] font-mono uppercase text-slate-500 block">Schedule Rate Norm</span>
                      <span className="font-bold font-mono text-slate-200">{formatINR(categoryBenchmark.avgCostPerUnit)}</span>
                    </div>
                    <div className="p-2.5 rounded bg-audit-950 border border-audit-800">
                      <span className="text-[10px] font-mono uppercase text-slate-500 block">Max Permissible</span>
                      <span className="font-bold font-mono text-slate-300">{formatINR(categoryBenchmark.maxPermissibleCost)}</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Section 4: Collapsible Financial History */}
          {project.disbursements && project.disbursements.length > 0 && (
            <div className="p-4 rounded-xl border border-audit-800 bg-audit-900/80 space-y-3">
              <button
                onClick={() => setShowDisbursements(!showDisbursements)}
                className="w-full flex items-center justify-between text-xs font-bold text-slate-300 font-mono"
              >
