                </div>
                {showDisbursements ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
              </button>

              {showDisbursements && (
                <div className="pt-2 border-t border-audit-800 overflow-x-auto">
                  <table className="w-full text-left text-xs">
                    <thead className="bg-audit-950 text-slate-400 font-mono text-[10px] uppercase">
                      <tr>
