                        <th className="py-2 px-2.5">Amount</th>
                        <th className="py-2 px-2.5">Date</th>
                        <th className="py-2 px-2.5">Milestone</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-audit-800">
                      {project.disbursements.map((d, i) => (
                        <tr key={i} className="hover:bg-audit-850">
                          <td className="py-2 px-2.5 font-mono text-slate-300">#{d.tranche}</td>
                          <td className="py-2 px-2.5 font-mono font-bold text-white">{formatINR(d.amount)}</td>
                          <td className="py-2 px-2.5 font-mono text-slate-400">{formatDate(d.date)}</td>
                          <td className="py-2 px-2.5 text-slate-400">{d.milestone}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}
