import { CATEGORY_BENCHMARKS } from "../data/projectsData.js";

/**
 * Tokenizes and normalizes text for NLP similarity matching
 */
function tokenizeText(str) {
  if (!str) return new Set();
  const stopWords = new Set([
    "and", "the", "of", "in", "for", "with", "at", "by", "from", "to", "a", "an",
    "village", "gram", "panchayat", "ward", "block", "district", "construction", "installation", "area",
    "gp", "mandal", "constituency", "reach", "work", "works", "under", "honble", "shri", "smt", "dr"
  ]);

  return new Set(
    str
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .split(/\s+/)
      .filter((word) => word.length > 2 && !stopWords.has(word))
  );
}

/**
 * Calculates Overlap Coefficient (Szymkiewicz–Simpson) and Jaccard
 */
function calculateSimilarity(setA, setB) {
  if (setA.size < 3 || setB.size < 3) return 0;
  let intersection = 0;
  for (const item of setA) {
    if (setB.has(item)) intersection++;
  }

  // Require at least 3 distinct matching keyword tokens
  if (intersection < 3) return 0;

  const minSize = Math.min(setA.size, setB.size);
  const overlapCoefficient = minSize === 0 ? 0 : intersection / minSize;
  const union = new Set([...setA, ...setB]).size;
  const jaccard = union === 0 ? 0 : intersection / union;

  return (overlapCoefficient * 0.7) + (jaccard * 0.3);
}

/**
 * Scans for Prohibited Asset creation under MPLADS Official Guidelines Schedule-II
 */
function checkProhibitedItems(project) {
  const fullText = `${project.title} ${project.description} ${project.category || ""}`.toLowerCase();

  const prohibitedPatterns = [
    {
      pattern: /private\s+trust|religious\s+trust|balaji\s+trust|trust\s+and\s+society|trust\s+campus|community\s+centre,\s+dollygunj/i,
      title: "Prohibited Work: Private / Religious Trust Property",
      explanation: "MPLADS Rule 3.2 strictly prohibits spending public funds on land/assets owned by private or religious trusts.",
      keyword: "PRIVATE / RELIGIOUS TRUST"
    },
    {
      pattern: /kalyana\s+mandapam|marriage\s+hall/i,
      title: "Prohibited Work: Non-Public Event Hall",
      explanation: "Creation of revenue-generating marriage halls or restricted community mandapams violates public access norms.",
      keyword: "KALYANA MANDAPAM"
    },
    {
      pattern: /commercial\s+complex|shopping\s+center|market\s+stalls\s+for\s+rent/i,
      title: "Prohibited Work: Commercial Asset",
      explanation: "Commercial revenue-generating assets for non-statutory bodies are barred under Schedule-II.",
      keyword: "COMMERCIAL ASSET"
    }
  ];

  for (const item of prohibitedPatterns) {
    if (item.pattern.test(fullText)) {
      return {
        type: "Compliance Violation",
        severity: "CRITICAL",
        title: item.title,
        explanation: item.explanation,
        metric: `Flagged Pattern: ${item.keyword}`,
        baseline: "MPLADS Permissible Works List (Schedule-I)",
        impactScore: 45
      };
    }
  }
  return null;
}

/**
 * Detects Cost Outlier / Estimation Overrun against Government Schedule of Rates (SOR)
 */
function checkCostAnomaly(project) {
  const benchmark = CATEGORY_BENCHMARKS[project.category] || CATEGORY_BENCHMARKS["Community Infrastructure"];
  if (!benchmark) return null;

  const baselineCost = benchmark.avgCostPerUnit;
  const sanctioned = project.sanctionedAmount;
  const deviation = ((sanctioned - baselineCost) / baselineCost) * 100;

  if (deviation > 35) {
    const isCritical = deviation > 80 || sanctioned > benchmark.maxPermissibleCost;
    return {
      type: "Cost Overrun",
      severity: isCritical ? "CRITICAL" : "HIGH",
      title: isCritical ? "Severe Cost Estimate Inflation" : "Unusual Cost Estimation Outlier",
      explanation: `Sanctioned budget of ₹${(sanctioned / 100000).toFixed(2)} Lakhs is ${deviation.toFixed(1)}% higher than the state average benchmark of ₹${(baselineCost / 100000).toFixed(2)} Lakhs for this category.`,
      metric: `₹${(sanctioned / 100000).toFixed(2)}L vs ₹${(baselineCost / 100000).toFixed(2)}L norm (+${deviation.toFixed(0)}%)`,
      baseline: `Norm: ₹${(baselineCost / 100000).toFixed(2)} Lakhs`,
      deviationPercent: Number(deviation.toFixed(1)),
      benchmarkCost: baselineCost,
      impactScore: Math.min(Math.round(deviation * 0.4), 45)
    };
  }
  return null;
}

/**
 * Checks for Duplicate Project Sanctions across all existing projects in dataset
 */
function checkDuplicateSanctions(project, allProjects) {
  const currentTokens = tokenizeText(`${project.title}`);
  let highestSimilarity = 0;
  let matchedProject = null;

  for (const other of allProjects) {
    if (other.id === project.id) continue;

    // Check same state and district / MP
    if (other.state === project.state && (other.district === project.district || other.mpName === project.mpName)) {
      const otherTokens = tokenizeText(`${other.title}`);
      const similarity = calculateSimilarity(currentTokens, otherTokens);

      if (similarity > highestSimilarity) {
        highestSimilarity = similarity;
        matchedProject = other;
      }
    }
  }

  if (highestSimilarity >= 0.55 && matchedProject) {
    const matchPercentage = Math.min(Math.round(highestSimilarity * 100), 98);
    const isCritical = highestSimilarity >= 0.70;

    return {
      type: "Duplicate Work",
      severity: isCritical ? "CRITICAL" : "HIGH",
      title: "Potential Duplicate Project Sanction",
      explanation: `High text and location overlap (${matchPercentage}% match) with project "${matchedProject.title}" (ID: ${matchedProject.workCode || matchedProject.id}) in ${matchedProject.district || matchedProject.state}. Potential double-billing or overlapping scope.`,
      metric: `${matchPercentage}% Match with ${matchedProject.workCode || matchedProject.id}`,
      baseline: `Distinct Unique Infrastructure Identity`,
      duplicateOf: {
        id: matchedProject.id,
        workCode: matchedProject.workCode,
        title: matchedProject.title,
        mpName: matchedProject.mpName,
        sanctionDate: matchedProject.sanctionDate,
        sanctionedAmount: matchedProject.sanctionedAmount,
        status: matchedProject.status
      },
      impactScore: Math.round(highestSimilarity * 50)
    };
  }
  return null;
}

/**
 * Detects Stalled Execution or Severe Timeline-Disbursement Disconnect
 */
function checkDelayAnomaly(project) {
  // If completed, not currently stalled
  if (project.status === "Completed") return null;

  const progress = project.physicalProgressPercent || 0;
  const expenditure = project.expenditureAmount || 0;
  const sanctioned = project.sanctionedAmount || 1;
  const financialDrawdownPct = (expenditure / sanctioned) * 100;

  // Stalled with high money spent
  if (project.status === "Stalled" || (progress < 30 && financialDrawdownPct >= 60)) {
    return {
      type: "Delayed Project",
      severity: "CRITICAL",
      title: "Stalled Work with High Financial Drawdown",
      explanation: `Project has utilized ${financialDrawdownPct.toFixed(0)}% of funds (₹${(expenditure / 100000).toFixed(1)}L), but physical progress is stalled at only ${progress}%. Work was scheduled for completion by ${project.targetCompletionDate || "2024-08-30"}.`,
      metric: `${financialDrawdownPct.toFixed(0)}% Disbursed vs ${progress}% Physical Progress`,
      baseline: `Target Completion: ${project.targetCompletionDate || "2024-08-30"}`,
      impactScore: 40
    };
  }

  // Overdue In-Progress project with slow progress
  if (project.status === "In Progress" && progress < 40 && financialDrawdownPct > 50) {
    return {
      type: "Delayed Project",
      severity: "HIGH",
      title: "Substantial Project Execution Lag",
      explanation: `Work progress is trailing financial disbursements with only ${progress}% progress certified.`,
      metric: `${financialDrawdownPct.toFixed(0)}% Disbursed vs ${progress}% Progress`,
      baseline: `Scheduled Phasing`,
      impactScore: 25
    };
  }

  return null;
}

/**
 * Detects Year-End Fiscal Rush (Sudden March spending spikes)
 */
function checkSpendingVelocity(project) {
  if (!project.disbursements || project.disbursements.length === 0) return null;

  let marchDisbursement = 0;
  for (const d of project.disbursements) {
    if (d.date && (d.date.includes("-03-25") || d.date.includes("-03-28") || d.date.includes("-03-29") || d.date.includes("-03-30") || d.date.includes("-03-31"))) {
      marchDisbursement += d.amount;
    }
  }

  const marchRatio = (marchDisbursement / (project.expenditureAmount || 1)) * 100;
  if (marchRatio >= 60 && (project.physicalProgressPercent || 0) < 50) {
    return {
      type: "Unusual Spending",
      severity: "HIGH",
      title: "Fiscal Year-End 'March Rush' Spike",
      explanation: `${marchRatio.toFixed(0)}% of total funds (₹${(marchDisbursement / 100000).toFixed(1)} Lakhs) were drawn in the final 5 days of March without corresponding physical milestone verification.`,
      metric: `${marchRatio.toFixed(0)}% Funds Cleared in March Final Week`,
      baseline: "Steady Phased Milestone Disbursement",
      impactScore: 30
    };
  }
  return null;
}

/**
 * Analyzes a single project and produces a comprehensive Forensic Risk Dossier
 */
export function analyzeProject(project, allProjects) {
  const anomalies = [];
  let totalScore = 0;

  // Run all detectors
  const prohibited = checkProhibitedItems(project);
  if (prohibited) {
    anomalies.push(prohibited);
    totalScore += prohibited.impactScore;
  }

  const costAnomaly = checkCostAnomaly(project);
  if (costAnomaly) {
    anomalies.push(costAnomaly);
    totalScore += costAnomaly.impactScore;
  }

  const duplicateAnomaly = checkDuplicateSanctions(project, allProjects);
  if (duplicateAnomaly) {
    anomalies.push(duplicateAnomaly);
    totalScore += duplicateAnomaly.impactScore;
  }

  const delayAnomaly = checkDelayAnomaly(project);
  if (delayAnomaly) {
    anomalies.push(delayAnomaly);
    totalScore += delayAnomaly.impactScore;
  }

  const velocityAnomaly = checkSpendingVelocity(project);
  if (velocityAnomaly) {
    anomalies.push(velocityAnomaly);
    totalScore += velocityAnomaly.impactScore;
  }

  // Normalize risk score to 0 - 100
  const riskScore = Math.min(Math.max(totalScore, 10), 98);

  let riskLevel = "LOW";
  if (riskScore >= 70 || anomalies.some(a => a.severity === "CRITICAL")) {
    riskLevel = "CRITICAL";
  } else if (riskScore >= 45 || anomalies.some(a => a.severity === "HIGH")) {
    riskLevel = "HIGH";
  } else if (riskScore >= 25 || anomalies.length > 0) {
    riskLevel = "MEDIUM";
  } else {
    riskLevel = "LOW";
  }

  // Primary classification
  const primaryAnomaly = anomalies.length > 0 ? anomalies[0].type : "Normal";

  // Decision Support Recommendations
  const decisionSupport = generateDecisionSupport(project, anomalies, riskLevel);

  return {
    ...project,
    riskScore: anomalies.length === 0 ? 12 : riskScore,
    riskLevel: anomalies.length === 0 ? "LOW" : riskLevel,
    primaryAnomaly,
    hasAnomalies: anomalies.length > 0,
    anomaliesCount: anomalies.length,
    anomalies,
    decisionSupport
  };
}

/**
 * Generates transparent decision-support actions for administrators
 */
function generateDecisionSupport(project, anomalies, riskLevel) {
  if (anomalies.length === 0) {
    return {
      urgency: "Routine",
      recommendedAction: "Standard Execution Oversight",
      actionCategory: "Approve / Monitor",
      auditChecklist: [
        "Review standard quarterly physical inspection certificate",
        "Verify final asset entry in district asset register upon completion"
      ],
      executiveSummary: "Project is operating within standard financial schedules and milestone delivery norms."
    };
  }

  const actions = [];
  const checklist = [];

  if (anomalies.some(a => a.type === "Duplicate Work")) {
    actions.push("Freeze Sanction & Conduct Site Cross-Verification");
    checklist.push("Cross-examine site coordinates with existing completed works in the same Panchayat");
    checklist.push("Issue notice to Implementing District Authority regarding suspected duplicate proposal");
  }

  if (anomalies.some(a => a.type === "Cost Overrun")) {
    actions.push("Order Cost Estimate & BOQ Audit");
    checklist.push("Request detailed Bill of Quantities (BOQ) and local Schedule of Rates (SOR) comparison");
    checklist.push("Verify contractor unit rates against state PWD benchmarks");
  }

  if (anomalies.some(a => a.type === "Delayed Project")) {
    actions.push("Order Physical Site Inspection & Bank Guarantee Review");
    checklist.push("Direct Executive Engineer to submit milestone delay justification within 7 days");
    checklist.push("Review contractor bank guarantee and initiate penalty clauses if applicable");
  }

  if (anomalies.some(a => a.type === "Compliance Violation")) {
    actions.push("Immediate Sanction Cancellation / Recovery Notice");
    checklist.push("Verify land title and ownership records to confirm non-commercial public ownership");
    checklist.push("Refer matter to State Nodal Authority for guideline non-compliance action");
  }

  if (anomalies.some(a => a.type === "Unusual Spending")) {
    actions.push("Audit March Disbursement Vouchers");
    checklist.push("Examine physical measurement books (MB) corresponding to year-end payment tranches");
  }

  return {
    urgency: riskLevel === "CRITICAL" ? "Immediate Action Required" : riskLevel === "HIGH" ? "Priority Investigation" : "Routine Audit",
    recommendedAction: actions[0] || "Conduct Forensic Document Review",
    actionCategory: riskLevel === "CRITICAL" ? "Freeze & Investigate" : "Audit & Verify",
    auditChecklist: checklist,
    executiveSummary: `System detected ${anomalies.length} anomaly flag(s) with ${riskLevel} severity rating. Key risk driver: ${anomalies[0].title}.`
  };
}

/**
 * Runs batch analysis on full dataset
 */
export function analyzeAllProjects(projects) {
  return projects.map((proj) => analyzeProject(proj, projects));
}

